from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class IpifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.set_interfaceDN(execution_config)

    def set_interfaceDN(self, execution_config):
        enb_id = self.enb_ent_config['id']
        self.set_parameter('ipMtu', 1500)

        if execution_config['vlan_id']:
            self.set_parameter('interfaceDN', f"MRBTS-{enb_id}/TNLSVC-1/TNL-1/ETHSVC-1/ETHIF-1/VLANIF-1")
        else:
            self.set_parameter('interfaceDN', f"MRBTS-{enb_id}/TNLSVC-1/TNL-1/ETHSVC-1/ETHIF-1")
